#include <bits/stdc++.h>
using namespace std;

bool fun(const vector<int>& p, int n, int sum, int i) {
    if (i == n) {
        return sum % 360 == 0;
    }
    return fun(p, n, sum + p[i], i + 1) || fun(p, n, sum - p[i], i + 1);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n)) return 0;
    vector<int> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    int sum = 0, k = 0;
    if (fun(a, n, sum, k)) {
        cout << "YES";
    } else {
        cout << "NO";
    }

    return 0;
}

